/**
 * @module shared/schema
 *
 * Central type definitions and validation schemas for the WoW addon dashboard.
 *
 * This module defines the domain model for the entire application, shared between
 * the Express backend and the React frontend. It uses:
 * - **TypeScript interfaces** for runtime-free type checking of domain objects.
 * - **Zod schemas** (prefixed `insert*Schema`) for runtime request-body validation
 *   on API routes. These mirror the interfaces but omit auto-generated fields
 *   (e.g. `id`) and add value-range constraints.
 * - **Inferred insert types** (`InsertX`) derived from Zod schemas via `z.infer`.
 *
 * Re-exports all Drizzle ORM table definitions and auth-related types from
 * `./models/auth` so consumers only need a single import path.
 *
 * Architecture note: The project does NOT use Drizzle tables for domain data
 * (APL entries, HUD configs, etc.) — those are persisted as JSON files on disk
 * by {@link server/storage}. Drizzle is used exclusively for the `sessions` and
 * `users` tables required by Replit Auth.
 */

import { createInsertSchema } from "drizzle-zod";
import { z } from "zod";

export * from "./models/auth";

/**
 * All playable World of Warcraft classes.
 * Used as a discriminator in {@link Spec} to associate specs with their parent class.
 */
export type WowClass =
  | "Death Knight" | "Demon Hunter" | "Druid" | "Evoker" | "Hunter"
  | "Mage" | "Monk" | "Paladin" | "Priest" | "Rogue"
  | "Shaman" | "Warlock" | "Warrior";

/**
 * Combat role categories for specializations.
 * Determines which APL priority list context applies (e.g. Tank specs may
 * prioritise defensive abilities differently).
 */
export type Role = "Tank" | "Healer" | "Melee DPS" | "Ranged DPS";

/**
 * Primary and secondary resource types used by WoW specializations.
 * Drives the resource-bar display on the HUD and resource-cap threshold logic.
 */
export type ResourceType = "Mana" | "Rage" | "Energy" | "Focus" | "Runic Power" | "Fury" | "Pain" | "Maelstrom" | "Essence" | "Combo Points" | "Soul Shards" | "Astral Power" | "Holy Power" | "Chi";

/**
 * A WoW class specialization descriptor.
 *
 * Specs are the top-level organisational unit — every APL entry, HUD config,
 * combat alert, and profile belongs to exactly one spec.
 *
 * @property id         - Unique slug identifier, e.g. `"frost-mage"`.
 * @property className  - Parent WoW class name.
 * @property specName   - Specialization display name, e.g. `"Frost"`.
 * @property role       - Combat role classification.
 * @property resource   - Primary resource type this spec uses.
 * @property classColor - Hex colour string for UI rendering, e.g. `"#69CCF0"`.
 * @property iconSlug   - WoW icon texture slug for the spec icon.
 */
export interface Spec {
  id: string;
  className: WowClass;
  specName: string;
  role: Role;
  resource: ResourceType;
  classColor: string;
  iconSlug: string;
}

/**
 * An Action Priority List entry — one row in a spec's rotation.
 *
 * APL entries are the core data the addon generator translates into Lua
 * condition/action pairs. They are ordered by {@link priority} (lower = higher
 * priority) and filtered by {@link mode} at runtime depending on detected
 * AoE target count.
 *
 * @property id              - UUID, auto-generated by storage.
 * @property specId          - Foreign key to {@link Spec.id}.
 * @property priority        - Numeric sort order (1 = highest priority).
 * @property spellName       - Display name of the spell/ability.
 * @property spellIcon       - WoW icon texture slug for the ability.
 * @property condition       - SimC-style condition expression, e.g. `"buff.icy_veins.up"`.
 * @property mode            - When this entry applies: single-target, AoE, or both.
 * @property isInterrupt     - Whether this entry is an interrupt ability.
 * @property isOffensive     - Whether this is an offensive cooldown.
 * @property enabled         - Toggle to disable without deleting.
 * @property keybind         - Player-assigned keybind string for display overlay.
 */
export interface AplEntry {
  id: string;
  specId: string;
  priority: number;
  spellName: string;
  spellIcon: string;
  condition: string;
  mode: "ST" | "AoE" | "Both";
  isInterrupt: boolean;
  isOffensive: boolean;
  isCooldown: boolean;
  enabled: boolean;
  keybind: string;
  isPrecombat: boolean;
  precombatType: "state" | "opener" | null;
  spellId?: number;
}

/**
 * Zod validation schema for creating/updating an APL entry.
 * Omits the auto-generated `id` field.
 * Used by the `POST /api/specs/:specId/apl` route for request body validation.
 */
export const insertAplEntrySchema = z.object({
  specId: z.string(),
  priority: z.number().int(),
  spellName: z.string().min(1),
  spellIcon: z.string(),
  condition: z.string(),
  mode: z.enum(["ST", "AoE", "Both"]),
  isInterrupt: z.boolean(),
  isOffensive: z.boolean(),
  isCooldown: z.boolean().optional().default(false),
  enabled: z.boolean(),
  keybind: z.string(),
  isPrecombat: z.boolean().optional().default(false),
  precombatType: z.enum(["state", "opener"]).nullable().optional().default(null),
  spellId: z.number().int().optional(),
});

/** Inferred TypeScript type for APL entry creation payloads. */
export type InsertAplEntry = z.infer<typeof insertAplEntrySchema>;

/**
 * Allowed positions for the keybind text overlay on HUD spell icons.
 * Controls where the keybind label is anchored relative to the icon frame.
 */
export type KeybindPosition = "bottom-right" | "top-right" | "top-left" | "bottom-left" | "center";

/**
 * Full HUD (Heads-Up Display) configuration for a specialization.
 *
 * Controls every visual aspect of the in-game overlay: icon sizes, positions,
 * opacity, queue depth, resource bar visibility, defensive thresholds, and more.
 * Each spec has exactly one HUD config. Profiles snapshot a subset of these
 * settings for quick switching.
 *
 * @property id                     - UUID, auto-generated by storage.
 * @property specId                 - Foreign key to {@link Spec.id}.
 * @property scale                  - Global UI scale multiplier (0.5–3).
 * @property opacity                - Frame opacity (0.3–1).
 * @property positionX              - Horizontal screen offset in pixels.
 * @property positionY              - Vertical screen offset in pixels.
 * @property iconSize               - Main ability icon size in pixels (20–96).
 * @property predIconSize           - Prediction/queue icon size in pixels (16–72).
 * @property queueSlots             - Number of upcoming abilities shown (1–5).
 * @property showKeybind            - Whether to overlay keybind text on icons.
 * @property keybindFontSize        - Font size for keybind overlay text (6–36).
 * @property keybindPosition        - Anchor position for keybind text on the icon.
 * @property showSpellName          - Whether to display spell names below icons.
 * @property spellNameFontSize      - Font size for spell name labels (7–16).
 * @property showCondition          - Whether to show the raw condition string (debug aid).
 * @property showResourceBar        - Whether to render the resource bar widget.
 * @property showHeader             - Whether to show the HUD header/title bar.
 * @property resourceCapThreshold   - Resource % at which the bar changes colour (50–100).
 * @property aoeThreshold           - Enemy count that triggers AoE-mode APL entries (2–10).
 * @property defaultModeDungeon     - Default rotation mode in dungeons ("AoE" or "ST").
 * @property defaultModeRaid        - Default rotation mode in raids ("AoE" or "ST").
 * @property defaultModeDelve       - Default rotation mode in delves ("AoE" or "ST").
 * @property defaultModeWorld       - Default rotation mode in open world/questing ("AoE" or "ST").
 * @property smartModeSwitch        - Auto-switch from ST to AoE when player casts an AoE spell.
 * @property showPrediction         - Whether to render predictive next-spell icons.
 * @property predictionOpacity      - Opacity for prediction icons (0.15–0.8).
 * @property framePadding           - Inner padding of the HUD frame in pixels (4–40).
 * @property iconSpacing            - Gap between ability icons in pixels (2–24).
 * @property lockPosition           - Prevents drag-repositioning when true.
 * @property debugMode              - Enables verbose debug output in the addon.
 * @property showCooldownText       - Renders remaining cooldown seconds on icons.
 * @property showGcdSpark           - Animates a GCD sweep spark on the current icon.
 * @property outOfCombatMode        - Shows a dimmed overlay when not in combat.
 * @property combatRole             - "auto" (default), "tank", or "dps". Auto enables tank mode when a tank spec is detected. Tank/DPS are manual overrides.
 * @property showDefensives         - Enables the defensive-ability suggestion layer.
 * @property defensiveThreshold     - Legacy HP% threshold for defensive suggestions (10–80).
 * @property defensiveThresholdMinor - HP% threshold for minor defensives (30–90).
 * @property defensiveThresholdMajor - HP% threshold for major defensives (10–50).
 * @property survivabilityMode      - Prioritises survival over DPS in suggestions.
 * @property showSelfHeals          - Includes self-heal abilities in suggestions.
 * @property formAwareness          - Filters spells by current shapeshift/stance form.
 * @property keybindBarPriority     - Ordered action bar names for keybind detection.
 * @property keybindOverrides       - Manual spell-name → keybind-string overrides.
 * @property interruptSound         - Play a sound when an interrupt opportunity appears.
 * @property interruptSoundId       - WoW Sound Kit ID for the interrupt alert (default 8959 = Raid Warning).
 * @property defensiveSound         - Play a sound when a defensive ability appears in slot 1.
 * @property defensiveSoundId       - WoW Sound Kit ID for the defensive alert (default 37666 = Boss Emote Warning).
 * @property healSound              - Play a sound when a self-heal ability appears in slot 1.
 * @property healSoundId            - WoW Sound Kit ID for the heal alert (default 8960 = Ready Check).
 * @property stSwitchSound          - Play a sound when switching to Single Target mode.
 * @property stSwitchSoundId        - WoW Sound Kit ID for the ST switch alert (default 3175 = Map Ping).
 * @property aoeSwitchSound         - Play a sound when switching to AoE mode.
 * @property aoeSwitchSoundId       - WoW Sound Kit ID for the AoE switch alert (default 8458 = PVP Enter Queue).
 */
export interface HudConfig {
  id: string;
  specId: string;
  scale: number;
  opacity: number;
  positionX: number;
  positionY: number;
  iconSize: number;
  predIconSize: number;
  queueSlots: number;
  showKeybind: boolean;
  keybindFontSize: number;
  keybindPosition: KeybindPosition;
  showSpellName: boolean;
  spellNameFontSize: number;
  showCondition: boolean;
  showResourceBar: boolean;
  showHeader: boolean;
  resourceCapThreshold: number;
  aoeThreshold: number;
  defaultModeDungeon: string;
  defaultModeRaid: string;
  defaultModeDelve: string;
  defaultModeWorld: string;
  smartModeSwitch: boolean;
  showPrediction: boolean;
  predictionOpacity: number;
  framePadding: number;
  iconSpacing: number;
  lockPosition: boolean;
  debugMode: boolean;
  showCooldownText: boolean;
  showGcdSpark: boolean;
  outOfCombatMode: boolean;
  combatRole: "auto" | "dps" | "tank";
  showDefensives: boolean;
  defensiveThreshold: number;
  defensiveThresholdMinor: number;
  defensiveThresholdMajor: number;
  survivabilityMode: boolean;
  showSelfHeals: boolean;
  formAwareness: boolean;
  keybindBarPriority: string[];
  keybindOverrides: Record<string, string>;
  interruptSound: boolean;
  interruptSoundId: number;
  defensiveSound: boolean;
  defensiveSoundId: number;
  healSound: boolean;
  healSoundId: number;
  stSwitchSound: boolean;
  stSwitchSoundId: number;
  aoeSwitchSound: boolean;
  aoeSwitchSoundId: number;
  potionEnabled: boolean;
  potionItemName: string;
  consumablesEnabled: boolean;
  flaskEnabled: boolean;
  flaskItemName: string;
  foodEnabled: boolean;
  foodItemName: string;
  weaponEnhEnabled: boolean;
  weaponEnhItemName: string;
  augmentRuneEnabled: boolean;
  augmentRuneItemName: string;
}

/**
 * Zod validation schema for creating/updating a HUD configuration.
 * Omits the auto-generated `id` field. Includes min/max constraints
 * matching the WoW client's supported value ranges.
 */
export const insertHudConfigSchema = z.object({
  specId: z.string(),
  scale: z.number().min(0.5).max(3),
  opacity: z.number().min(0.3).max(1),
  positionX: z.number(),
  positionY: z.number(),
  iconSize: z.number().min(20).max(96),
  predIconSize: z.number().min(16).max(72),
  queueSlots: z.number().int().min(1).max(5),
  showKeybind: z.boolean(),
  keybindFontSize: z.number().min(6).max(36),
  keybindPosition: z.enum(["bottom-right", "top-right", "top-left", "bottom-left", "center"]),
  showSpellName: z.boolean(),
  spellNameFontSize: z.number().min(7).max(16),
  showCondition: z.boolean(),
  showResourceBar: z.boolean(),
  showHeader: z.boolean(),
  resourceCapThreshold: z.number().min(50).max(100),
  aoeThreshold: z.number().min(2).max(10),
  defaultModeDungeon: z.enum(["AoE", "ST"]).optional().default("AoE"),
  defaultModeRaid: z.enum(["AoE", "ST"]).optional().default("AoE"),
  defaultModeDelve: z.enum(["AoE", "ST"]).optional().default("AoE"),
  defaultModeWorld: z.enum(["AoE", "ST"]).optional().default("AoE"),
  smartModeSwitch: z.boolean().optional().default(true),
  showPrediction: z.boolean(),
  predictionOpacity: z.number().min(0.15).max(0.8),
  framePadding: z.number().min(4).max(40),
  iconSpacing: z.number().min(2).max(24),
  lockPosition: z.boolean(),
  debugMode: z.boolean(),
  showCooldownText: z.boolean(),
  showGcdSpark: z.boolean(),
  outOfCombatMode: z.boolean(),
  combatRole: z.enum(["auto", "dps", "tank"]).optional().default("auto"),
  showDefensives: z.boolean().optional().default(false),
  defensiveThreshold: z.number().min(10).max(80),
  defensiveThresholdMinor: z.number().min(30).max(90).optional().default(60),
  defensiveThresholdMajor: z.number().min(10).max(50).optional().default(30),
  survivabilityMode: z.boolean().optional().default(false),
  showSelfHeals: z.boolean().optional().default(false),
  formAwareness: z.boolean().optional().default(true),
  keybindBarPriority: z.array(z.string()).optional().default(["Main Action Bar", "Bottom Left", "Bottom Right", "Right Bar 1", "Right Bar 2"]),
  keybindOverrides: z.record(z.string(), z.string()).optional().default({}),
  interruptSound: z.boolean(),
  interruptSoundId: z.number().int().optional().default(8959),
  defensiveSound: z.boolean().optional().default(true),
  defensiveSoundId: z.number().int().optional().default(37666),
  healSound: z.boolean().optional().default(true),
  healSoundId: z.number().int().optional().default(8960),
  stSwitchSound: z.boolean().optional().default(true),
  stSwitchSoundId: z.number().int().optional().default(3175),
  aoeSwitchSound: z.boolean().optional().default(true),
  aoeSwitchSoundId: z.number().int().optional().default(8458),
  potionEnabled: z.boolean().optional().default(false),
  potionItemName: z.string().optional().default(""),
  consumablesEnabled: z.boolean().optional().default(true),
  flaskEnabled: z.boolean().optional().default(true),
  flaskItemName: z.string().optional().default(""),
  foodEnabled: z.boolean().optional().default(true),
  foodItemName: z.string().optional().default(""),
  weaponEnhEnabled: z.boolean().optional().default(true),
  weaponEnhItemName: z.string().optional().default(""),
  augmentRuneEnabled: z.boolean().optional().default(true),
  augmentRuneItemName: z.string().optional().default(""),
});

/** Inferred TypeScript type for HUD config creation/update payloads. */
export type InsertHudConfig = z.infer<typeof insertHudConfigSchema>;

/**
 * A boss-mod combat alert configuration.
 *
 * Links a boss-mod event (from DBM, BigWigs, or a custom trigger) to a
 * specific interrupt or reaction spell. The addon listens for these events
 * and highlights the mapped ability on the HUD.
 *
 * @property id             - UUID, auto-generated by storage.
 * @property specId         - Foreign key to {@link Spec.id}.
 * @property alertName      - Human-readable name for this alert rule.
 * @property source         - Which boss-mod framework fires this alert.
 * @property spellId        - WoW spell ID string that triggers the alert.
 * @property interruptSpell - Name of the ability to highlight in response.
 * @property priority       - Urgency tier affecting HUD glow intensity/sound.
 * @property enabled        - Toggle to disable without deleting.
 */
export interface CombatAlert {
  id: string;
  specId: string;
  alertName: string;
  source: "DBM" | "BigWigs" | "Custom";
  spellId: string;
  interruptSpell: string;
  priority: "Critical" | "High" | "Medium";
  enabled: boolean;
}

/**
 * Zod validation schema for creating/updating a combat alert.
 * Omits the auto-generated `id` field.
 */
export const insertCombatAlertSchema = z.object({
  specId: z.string(),
  alertName: z.string().min(1),
  source: z.enum(["DBM", "BigWigs", "Custom"]),
  spellId: z.string(),
  interruptSpell: z.string(),
  priority: z.enum(["Critical", "High", "Medium"]),
  enabled: z.boolean(),
});

/** Inferred TypeScript type for combat alert creation payloads. */
export type InsertCombatAlert = z.infer<typeof insertCombatAlertSchema>;

/**
 * A saved HUD settings profile for quick switching.
 *
 * Profiles snapshot a subset of {@link HudConfig} fields (excluding `id` and
 * `specId`) along with keybind overrides, allowing players to swap between
 * preset configurations (e.g. raid vs. M+ layouts).
 *
 * @property id               - UUID, auto-generated by storage.
 * @property name             - User-facing profile name.
 * @property specId           - Foreign key to {@link Spec.id}.
 * @property hudConfig        - Snapshot of HUD settings (without `id`/`specId`).
 * @property keybindOverrides - Spell-name → keybind-string mapping overrides.
 * @property createdAt        - ISO 8601 timestamp of profile creation.
 */
export interface Profile {
  id: string;
  name: string;
  specId: string;
  hudConfig: Omit<HudConfig, "id" | "specId">;
  keybindOverrides: Record<string, string>;
  createdAt: string;
}

/**
 * Zod validation schema for creating a new profile.
 * Only requires a name and specId; hudConfig and keybindOverrides are optional
 * and default to empty objects if not provided.
 */
export const insertProfileSchema = z.object({
  name: z.string().min(1).max(64),
  specId: z.string(),
  hudConfig: z.record(z.unknown()).optional(),
  keybindOverrides: z.record(z.string(), z.string()).optional().default({}),
});

/** Inferred TypeScript type for profile creation payloads. */
export type InsertProfile = z.infer<typeof insertProfileSchema>;

/**
 * Record of a single addon sync/build run.
 *
 * Created each time the sync engine generates a new addon version and
 * (optionally) uploads it to CurseForge.
 *
 * @property id                  - UUID, auto-generated.
 * @property startedAt           - ISO 8601 timestamp when the run started.
 * @property completedAt         - ISO 8601 timestamp when the run finished, or null if still running.
 * @property status              - Current state of the run.
 * @property simcSpecs           - Number of specs that used SimC-sourced APL data.
 * @property fallbackSpecs       - Number of specs that fell back to manual/default APL data.
 * @property addonVersion        - Semantic version string of the generated addon, e.g. `"1.2.3"`.
 * @property curseforgeUploaded  - Whether the build was successfully uploaded to CurseForge.
 * @property error               - Error message if the run failed, otherwise null.
 * @property triggeredBy         - Whether this run was started by the 24h scheduler or manually.
 */
export interface SyncRun {
  id: string;
  startedAt: string;
  completedAt: string | null;
  status: "running" | "success" | "error" | "skipped";
  simcSpecs: number;
  fallbackSpecs: number;
  addonVersion: string;
  curseforgeUploaded: boolean;
  error: string | null;
  triggeredBy: "schedule" | "manual";
}

/**
 * Aggregate sync engine state exposed to the admin dashboard.
 *
 * Combines the latest run outcome with the full run history, enabling the
 * admin UI to display current status, last error, version, and a timeline
 * of past sync runs.
 *
 * @property lastSyncTime   - ISO 8601 timestamp of the most recent completed sync, or null.
 * @property lastSyncStatus - Outcome of the most recent sync, or null if never run.
 * @property lastError      - Error message from the last failed sync, or null.
 * @property currentVersion - Current addon version string.
 * @property isRunning      - Whether a sync is currently in progress.
 * @property history        - Array of past {@link SyncRun} records, newest first.
 */
export interface SyncState {
  lastSyncTime: string | null;
  lastSyncStatus: "success" | "error" | "skipped" | null;
  lastError: string | null;
  currentVersion: string;
  isRunning: boolean;
  lastDataHash: string | null;
  history: SyncRun[];
}
